ALTER TABLE m_exchange_rate
ADD CONSTRAINT ck_exchange_rate_distinct_currencies
CHECK (source_currency_code <> target_currency_code);

ALTER TABLE m_exchange_rate
ADD CONSTRAINT ck_exchange_rate_effective_range
CHECK (effective_to IS NULL OR effective_to >= effective_from);

INSERT INTO m_permission (grouping, code, entity_name, action_name, can_maker_checker)
SELECT 'self_service', 'READ_EXCHANGE_RATE', 'EXCHANGE_RATE', 'READ', false
WHERE NOT EXISTS (SELECT 1 FROM m_permission WHERE code = 'READ_EXCHANGE_RATE');

